export function icon(name, className = "") {
  return `<svg class="icon ${className}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.info}</svg>`;
}
// Ô tick: chỉ phần hộp (cả dòng là một <button role="checkbox">)
export function k7CheckMark(checked, disabled = false) {
  return `<span class="k7-check__box${checked ? " is-checked" : ""}${disabled ? " is-disabled" : ""}" aria-hidden="true">${checked ? icon("check", "icon--sm") : ""}</span>`;
}
